H("759.d.4.E",3,"A chart lists arraignment, jury selection, opening statements, evidence, closings, verdict and sentencing. This identifies the:","trial process from pretrial to sentencing",["lunch menu","school calendar","bus schedule"],"Trial steps follow a sequence.")
H("759.d.4.E",4,"Which step comes immediately before closing arguments?","presentation of evidence",["sentencing","jury selection","arraignment"],"Evidence precedes closings.")
H("759.d.4.F",3,"Students review a fictional case file, weigh evidence and decide what charges apply. This evaluates:","a simulated criminal case",["a cooking contest","a fashion show","a soccer match"],"Simulations teach case analysis.")
H("759.d.4.F",4,"In a case simulation, strong analysis relies on:","facts, law and logical reasoning",["guesses","rumors","favorites"],"Reason from evidence.")
H("759.d.4.G",3,"Students play judge, jurors, attorneys and witnesses in a courtroom exercise with real procedure. This is a:","mock trial of the criminal trial procedure",["dance recital","science fair","book sale"],"Mock trials teach process.")
H("759.d.4.G",4,"In a mock trial, an attorney's opening statement:","outlines what the evidence will show",["gives the verdict","gives the sentence","argues the law only"],"Openings preview the case.")
H("759.d.5.A",3,"An officer must have a reasonable basis before searching a car, honoring the amendment that protects against unreasonable searches. This applies the:","Fourth Amendment responsibilities of police",["First Amendment","Second Amendment","Third Amendment"],"The Fourth Amendment regulates searches.")
H("759.d.5.A",4,"A deputy wants to open a locked backpack with no warrant and no emergency. Which constitutional protection limits this?","the Fourth Amendment ban on unreasonable searches",["the Third Amendment ban on quartering soldiers","the Second Amendment right to bear arms","the Twelfth Amendment rules on electors"],"Searches generally need a warrant or an exception.")
H("759.d.5.B",3,"A trainee reviews a scenario where an officer enters a home without a warrant and decides if it fits an exception. This determines if the search was:","proper under constitutional provisions",["popular","fast","quiet"],"Compare facts to exceptions.")
H("759.d.5.B",4,"A search warrant is usually required unless:","an exception such as exigent circumstances applies",["it is a weekday","the officer is in uniform","the home is large"],"Exceptions are narrow.")
H("759.d.5.C",3,"Evidence found through an illegal stop is thrown out, along with additional evidence found because of it. This analyzes the exclusionary rule and:","the fruit of the poisonous tree doctrine",["the double jeopardy clause","the speedy trial rule","the jury duty rule"],"Derivative evidence is also excluded.")
H("759.d.5.C",4,"Under the fruit of the poisonous tree doctrine, evidence derived from an illegal search is generally:","inadmissible",["always admissible","automatically strong","required"],"Taint spreads to derivative evidence.")
